import time

class RaftReadGuard:
    def __init__(self, election_timeout_s=1.0, max_drift_factor=1.05):
        self.election_timeout = election_timeout_s
        self.max_drift = max_drift_factor
        self.lease_expiry = 0.0

    def on_heartbeat_quorum_ack(self, send_monotonic_ts: float):
        # Bound lease from heartbeat SEND time, never receive time!
        safe_window = (self.election_timeout / self.max_drift) * 0.8
        self.lease_expiry = send_monotonic_ts + safe_window

    def can_serve_lease_read(self) -> bool:
        return time.monotonic() < self.lease_expiry
